def integrate_all_missing():
    knowledge_path = "datasets/destinations/destinations_rich_knowledge.json"
    with open(knowledge_path, "r", encoding="utf-8") as f:
        existing = json.load(f)

    replaced = set(ADDITIONAL_GLOBAL_DATA.keys())
    kept = [d for d in existing if d.get("city") not in replaced and d.get("country") not in replaced]

    new_items = []
    for dest, pois in ADDITIONAL_GLOBAL_DATA.items():
        for p in pois:
            p["city"] = dest
            p["region"] = "Asia" if dest in ["Mumbai", "Bengaluru"] else ("North America" if dest in ["USA", "Mexico"] else "Global")
            p["country"] = "India" if dest in ["Mumbai", "Bengaluru"] else dest
            new_items.append(p)

    final_knowledge = new_items + kept
    with open(knowledge_path, "w", encoding="utf-8") as f:
        json.dump(final_knowledge, f, indent=2)

    print(f"Added all missing destinations! Total POIs in database: {len(final_knowledge)}")

if __name__ == "__main__":
    integrate_all_missing()
